#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <OneWire.h>
#include <DallasTemperature.h>
#include <Servo.h>
#include <EEPROM.h>

// ===== Дисплей =====
#define SCREEN_W 128
#define SCREEN_H 64
#define OLED_ADDR 0x3C
Adafruit_SSD1306 dsp(SCREEN_W, SCREEN_H, &Wire, -1);

// ===== Пины =====
#define PIN_CLK   2
#define PIN_DT    3
#define PIN_SW    4
#define PIN_BACK  5
#define PIN_OK    6
#define PIN_DS    7
#define PIN_SERVO 9

// ===== Периферия =====
OneWire           ow(PIN_DS);
DallasTemperature ts(&ow);
Servo             srv;

// ===== Конечный автомат =====
enum St {
  NORMAL, MENU,
  SET_TEMP,
  SET_KP, SET_KI, SET_KD,
  AUTOTUNE,
  SET_DELTA, SET_TIMER,
  CAL_MIN, CAL_MAX,
  PRESET_LIST, PRESET_ACTION, PRESET_NAME
};
St st = NORMAL;

// ===== Меню =====
const int N_MENU = 8;
const char* menu[N_MENU] = {
  "Set Temperature",
  "PID Coefficients",
  "Auto Tune PID",
  "Timer Settings",
  "Calibrate Servo",
  "Temp Presets",
  "PID Presets",
  "Exit"
};
int menuIdx = 0;

// ===== EEPROM — базовые =====
#define EE_MAGIC  0   // byte
#define EE_MIN    1   // int   1–2
#define EE_MAX    3   // int   3–4
#define EE_SP     5   // float 5–8
#define EE_KP     9   // float 9–12
#define EE_KI     13  // float 13–16
#define EE_KD     17  // float 17–20
#define EE_TDELTA 21  // float 21–24
#define EE_TDUR   25  // int   25–26

// ===== Пресеты =====
#define NAME_LEN       17
#define N_PRESETS      18
#define PRESET_VALID   0x55

#define PT_BASE        27
#define PT_SLOT_SIZE   (4 + 2 + 1 + NAME_LEN)            // 24

#define PP_BASE        (PT_BASE + N_PRESETS * PT_SLOT_SIZE)  // 459
#define PP_SLOT_SIZE   (4 + 4 + 4 + 1 + NAME_LEN)           // 30
// Итого: 459 + 18*30 = 999 из 1024

// ===== Глобальные переменные =====
int   sMin = 0, sMax = 180, sPos = 90;
float setpoint = 25.0;
float Kp = 5.0, Ki = 0.5, Kd = 2.0;
float timerDelta = 2.0;
int   timerDuration = 0;
float editVal = 0.0;

// Таймер
enum TmState { TM_OFF, TM_IDLE, TM_RUN, TM_DONE };
TmState tmSt = TM_OFF;
unsigned long tmStartT = 0;
unsigned long tmRemain = 0;

// Энкодер
int lastClk = HIGH;

// Кнопки
bool bBack = false, bOk = false, bSw = false;
unsigned long dbBack = 0, dbOk = 0, dbSw = 0;
#define DB_MS 50

// Температура
float  temp = 0.0;
bool   tErr = false;
bool   tReq = false;
bool   tempReady = false;
unsigned long tReqT = 0, tLast = 0;
#define T_INTERVAL 2000
#define T_CONV     200

// ПИД
float pidIntegral = 0.0;
float pidPrevErr  = 0.0;
float pidOutput   = 0.0;
unsigned long pidLastT = 0;

// Автонастройка
enum ATPhase { AT_OFF, AT_HEAT, AT_SETTLE, AT_RESULT };
ATPhase atPhase = AT_OFF;
#define AT_MAX_SAMPLES 60
#define AT_MARGIN 5.0
#define AT_SLOPE_THRESH 0.05
#define AT_TIMEOUT_MS 1800000UL
#define AT_SETTLE_TIMEOUT 60000UL
#define AT_RESULT_DISPLAY 3000UL
float  atTemps[AT_MAX_SAMPLES];
int    atSampleCount = 0;
unsigned long atStartTime = 0;
unsigned long atSettleStart = 0;
unsigned long atResultTime = 0;
float  atR = 0;
float  atL = 0;
float  atKp = 0, atKi = 0, atKd = 0;
bool   atDone = false;
bool   atSuccess = false;
bool   atAutomatic = false;
bool   atSessionDone = false;
bool   atAutoStartPending = true;

// Пресеты
int   presetSlot = 0;
int   presetActionIdx = 0;
bool  presetIsTemp = true;
bool  lastActionWasErase = false;

// Редактор имени
const char charset[] = " ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-";
const int charsetLen = 38;
char  nameBuf[NAME_LEN + 1];
int   nameCursor = 0;
int   nameCharIdx[NAME_LEN];

// UI
bool redraw = true;
unsigned long savedT = 0;

// =======================================================
// Пресеты — чтение/запись/стирание
// =======================================================
void readTempPreset(int slot, float &sp, int &dur, char *name, bool &valid) {
  int base = PT_BASE + slot * PT_SLOT_SIZE;
  EEPROM.get(base, sp);
  EEPROM.get(base + 4, dur);
  valid = (EEPROM.read(base + 6) == PRESET_VALID);
  for (int i = 0; i < NAME_LEN; i++)
    name[i] = EEPROM.read(base + 7 + i);
  name[NAME_LEN] = '\0';
}

void writeTempPreset(int slot, float sp, int dur, const char *name) {
  int base = PT_BASE + slot * PT_SLOT_SIZE;
  EEPROM.put(base, sp);
  EEPROM.put(base + 4, dur);
  EEPROM.write(base + 6, PRESET_VALID);
  for (int i = 0; i < NAME_LEN; i++)
    EEPROM.write(base + 7 + i, name[i]);
}

void eraseTempPreset(int slot) {
  int base = PT_BASE + slot * PT_SLOT_SIZE;
  EEPROM.write(base + 6, 0x00);
}

void readPIDPreset(int slot, float &kp, float &ki, float &kd, char *name, bool &valid) {
  int base = PP_BASE + slot * PP_SLOT_SIZE;
  EEPROM.get(base, kp);
  EEPROM.get(base + 4, ki);
  EEPROM.get(base + 8, kd);
  valid = (EEPROM.read(base + 12) == PRESET_VALID);
  for (int i = 0; i < NAME_LEN; i++)
    name[i] = EEPROM.read(base + 13 + i);
  name[NAME_LEN] = '\0';
}

void writePIDPreset(int slot, float kp, float ki, float kd, const char *name) {
  int base = PP_BASE + slot * PP_SLOT_SIZE;
  EEPROM.put(base, kp);
  EEPROM.put(base + 4, ki);
  EEPROM.put(base + 8, kd);
  EEPROM.write(base + 12, PRESET_VALID);
  for (int i = 0; i < NAME_LEN; i++)
    EEPROM.write(base + 13 + i, name[i]);
}

void erasePIDPreset(int slot) {
  int base = PP_BASE + slot * PP_SLOT_SIZE;
  EEPROM.write(base + 12, 0x00);
}

void initNameEditor() {
  char curName[NAME_LEN + 1];
  bool valid;
  if (presetIsTemp) {
    float sp; int dur;
    readTempPreset(presetSlot, sp, dur, curName, valid);
  } else {
    float kp, ki, kd;
    readPIDPreset(presetSlot, kp, ki, kd, curName, valid);
  }
  if (valid) {
    for (int i = 0; i < NAME_LEN; i++) {
      nameBuf[i] = curName[i];
      nameCharIdx[i] = 0;
      for (int j = 0; j < charsetLen; j++) {
        if (charset[j] == curName[i]) { nameCharIdx[i] = j; break; }
      }
    }
  } else {
    for (int i = 0; i < NAME_LEN; i++) {
      nameBuf[i] = ' ';
      nameCharIdx[i] = 0;
    }
  }
  nameBuf[NAME_LEN] = '\0';
  nameCursor = 0;
}

void savePresetWithName() {
  if (presetIsTemp)
    writeTempPreset(presetSlot, setpoint, timerDuration, nameBuf);
  else
    writePIDPreset(presetSlot, Kp, Ki, Kd, nameBuf);
  savedT = millis();
}

// =======================================================
// Вывод имени
// =======================================================
void printName(const char *name) {
  int last = NAME_LEN - 1;
  while (last >= 0 && name[last] == ' ') last--;
  for (int i = 0; i <= last; i++)
    dsp.print(name[i]);
}

void printNameTwoLines(const char *name) {
  int half = (NAME_LEN + 1) / 2;  // 9
  int last = NAME_LEN - 1;
  while (last >= 0 && name[last] == ' ') last--;
  if (last < 0) { dsp.println("[empty]"); return; }
  for (int i = 0; i < half && i <= last; i++)
    dsp.print(name[i]);
  dsp.println("");
  if (last >= half) {
    for (int i = half; i <= last; i++)
      dsp.print(name[i]);
  }
  dsp.println("");
}

// =======================================================
void setup() {
  Serial.begin(115200);

  pinMode(PIN_CLK,  INPUT_PULLUP);
  pinMode(PIN_DT,   INPUT_PULLUP);
  pinMode(PIN_SW,   INPUT_PULLUP);
  pinMode(PIN_BACK, INPUT_PULLUP);
  pinMode(PIN_OK,   INPUT_PULLUP);

  if (EEPROM.read(EE_MAGIC) == 0x55) {
    EEPROM.get(EE_MIN, sMin);
    EEPROM.get(EE_MAX, sMax);
    EEPROM.get(EE_SP,  setpoint);
    EEPROM.get(EE_KP,  Kp);
    EEPROM.get(EE_KI,  Ki);
    EEPROM.get(EE_KD,  Kd);
    EEPROM.get(EE_TDELTA, timerDelta);
    EEPROM.get(EE_TDUR,   timerDuration);
  } else {
    for (int i = 0; i < N_PRESETS; i++) {
      eraseTempPreset(i);
      erasePIDPreset(i);
    }
    saveAllEEPROM();
  }
  sMin = constrain(sMin, 0, 179);
  sMax = constrain(sMax, 1, 180);
  if (sMin >= sMax) { sMin = 0; sMax = 180; }
  setpoint      = constrain(setpoint, 0.0, 100.0);
  Kp            = constrain(Kp, 0.0, 50.0);
  Ki            = constrain(Ki, 0.0, 5.0);
  Kd            = constrain(Kd, 0.0, 20.0);
  timerDelta    = constrain(timerDelta, 0.0, 20.0);
  timerDuration = constrain(timerDuration, 0, 600);
  sPos = (sMin + sMax) / 2;
  tmSt = (timerDuration > 0) ? TM_IDLE : TM_OFF;

  if (!dsp.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println(F("OLED not found"));
    for (;;);
  }
  dsp.setTextSize(1);
  dsp.setTextColor(SSD1306_WHITE);

  ts.begin();
  ts.setResolution(10);
  ts.setWaitForConversion(false);

  srv.attach(PIN_SERVO);
  srv.write(sPos);
  pidLastT = millis();

  ts.requestTemperatures();
  tReq = true;
  tReqT = millis();
  lastClk = digitalRead(PIN_CLK);
}

// =======================================================
void saveAllEEPROM() {
  EEPROM.put(EE_MIN, sMin);
  EEPROM.put(EE_MAX, sMax);
  EEPROM.put(EE_SP,  setpoint);
  EEPROM.put(EE_KP,  Kp);
  EEPROM.put(EE_KI,  Ki);
  EEPROM.put(EE_KD,  Kd);
  EEPROM.put(EE_TDELTA, timerDelta);
  EEPROM.put(EE_TDUR,   timerDuration);
  EEPROM.write(EE_MAGIC, 0x55);
}

void resetPID() {
  pidIntegral = 0.0;
  pidPrevErr  = 0.0;
  pidLastT    = millis();
}

void enterNormal() {
  st = NORMAL;
  sPos = constrain(sPos, sMin, sMax);
  if (tmSt == TM_DONE)
    tmSt = (timerDuration > 0) ? TM_IDLE : TM_OFF;
  srv.write(sPos);
  resetPID();
  tempReady = false;
}

// =======================================================
// Автонастройка
// =======================================================
void startAutoTune(bool automatic) {
  st = AUTOTUNE;
  atPhase = AT_HEAT;
  atAutomatic = automatic;
  atSampleCount = 0;
  atStartTime = millis();
  atR = 0;
  atL = 0;
  atDone = false;
  atSuccess = false;
  sPos = sMax;
  srv.write(sPos);
  Serial.print("Auto-tune STARTED (");
  Serial.print(automatic ? "auto" : "manual");
  Serial.println(")");
}

void updateAutoTune() {
  if (atDone) return;
  unsigned long now = millis();

  if (now - atStartTime > AT_TIMEOUT_MS) {
    atSuccess = false; atDone = true;
    atPhase = AT_RESULT; atResultTime = now;
    sPos = sMin; srv.write(sPos);
    Serial.println("Auto-tune TIMEOUT");
    return;
  }
  if (tErr) {
    atSuccess = false; atDone = true;
    atPhase = AT_RESULT; atResultTime = now;
    sPos = sMin; srv.write(sPos);
    Serial.println("Auto-tune ABORT: sensor");
    return;
  }

  if (atSampleCount < AT_MAX_SAMPLES) {
    atTemps[atSampleCount] = temp;
    atSampleCount++;
  }

  float slope = 0;
  if (atSampleCount >= 3)
    slope = (atTemps[atSampleCount - 1] - atTemps[atSampleCount - 3]) / 4.0;

  if (atPhase == AT_HEAT) {
    sPos = sMax;
    srv.write(sPos);
    if (atL == 0 && atSampleCount >= 3 && slope > AT_SLOPE_THRESH) {
      atL = (atSampleCount - 2) * (T_INTERVAL / 1000.0);
    }
    if (slope > atR) atR = slope;
    if (atSampleCount > 30 && atR < AT_SLOPE_THRESH) {
      atSuccess = false; atDone = true;
      atPhase = AT_RESULT; atResultTime = now;
      sPos = sMin; srv.write(sPos);
      Serial.println("Auto-tune FAILED: no rise");
      return;
    }
    if (temp >= setpoint - AT_MARGIN) {
      atPhase = AT_SETTLE;
      atSettleStart = now;
      sPos = sMin; srv.write(sPos);
      Serial.println("Auto-tune: cut heat");
    }
    if (temp >= setpoint) {
      atPhase = AT_SETTLE;
      atSettleStart = now;
      sPos = sMin; srv.write(sPos);
      Serial.println("Auto-tune: SAFETY CUT");
    }
  }

  if (atPhase == AT_SETTLE) {
    sPos = sMin;
    srv.write(sPos);
    bool dropping = (atSampleCount >= 3 && slope < -0.01);
    bool settleTimeout = (now - atSettleStart > AT_SETTLE_TIMEOUT);
    bool safetyCut = (temp >= setpoint);
    if (dropping || settleTimeout || safetyCut) {
      if (atR > 0.01 && atL >= 0.5) {
        atKp = 120.0 / (atR * atL);
        atKi = atKp / (2.0 * atL);
        atKd = atKp * atL / 2.0;
        atKp = constrain(atKp, 0.0, 50.0);
        atKi = constrain(atKi, 0.0, 5.0);
        atKd = constrain(atKd, 0.0, 20.0);
        atSuccess = true;
      } else {
        atSuccess = false;
      }
      atDone = true;
      atPhase = AT_RESULT;
      atResultTime = now;
    }
  }
}

void applyAutoTuneResults() {
  if (atSuccess) {
    Kp = atKp; Ki = atKi; Kd = atKd;
    saveAllEEPROM();
    savedT = millis();
    Serial.println("Auto-tune PID applied");
  }
  atSessionDone = true;
  enterNormal();
}

// =======================================================
void computePID() {
  float err = setpoint - temp;
  unsigned long now = millis();
  float dt = (now - pidLastT) / 1000.0;
  if (dt <= 0) dt = 0.001;
  pidLastT = now;
  pidIntegral += err * dt;
  pidIntegral = constrain(pidIntegral, -50.0, 50.0);
  float deriv = (err - pidPrevErr) / dt;
  pidPrevErr = err;
  pidOutput = Kp * err + Ki * pidIntegral + Kd * deriv;
  float out = constrain(pidOutput, 0.0, 100.0);
  sPos = (int)(sMin + out / 100.0 * (sMax - sMin));
  sPos = constrain(sPos, sMin, sMax);
  srv.write(sPos);
}

// =======================================================
void updateTimer() {
  if (tmSt == TM_OFF) return;
  if (tmSt == TM_IDLE) {
    if (!tErr && temp >= (setpoint - timerDelta)) {
      tmSt = TM_RUN;
      tmStartT = millis();
      tmRemain = (unsigned long)timerDuration * 60UL;
    }
  }
  if (tmSt == TM_RUN) {
    unsigned long elapsed = (millis() - tmStartT) / 1000UL;
    unsigned long total = (unsigned long)timerDuration * 60UL;
    if (elapsed >= total) {
      tmSt = TM_DONE;
      sPos = sMin;
      srv.write(sPos);
    } else {
      tmRemain = total - elapsed;
    }
  }
}

// =======================================================
void loop() {
  pollEnc();
  pollBtns();
  pollTemp();

  if (atAutoStartPending && !tErr && temp > -100.0) {
    atAutoStartPending = false;
    if (!atSessionDone && temp < setpoint - 10.0 && st == NORMAL)
      startAutoTune(true);
  }

  if (st == AUTOTUNE && (atPhase == AT_HEAT || atPhase == AT_SETTLE) && tempReady) {
    updateAutoTune();
    tempReady = false;
    redraw = true;
  }

  if (st == AUTOTUNE && atPhase == AT_RESULT && atAutomatic &&
      millis() - atResultTime > AT_RESULT_DISPLAY) {
    applyAutoTuneResults();
    redraw = true;
  }

  static unsigned long lastTmCheck = 0;
  if (millis() - lastTmCheck > 1000) {
    lastTmCheck = millis();
    if (st == NORMAL && (tmSt == TM_IDLE || tmSt == TM_RUN)) {
      updateTimer();
      redraw = true;
    }
  }

  if (st == NORMAL && tempReady && !tErr && tmSt != TM_DONE) {
    computePID();
    tempReady = false;
    redraw = true;
  }

  if (savedT > 0 && millis() - savedT >= 800) {
    savedT = 0;
    redraw = true;
  }
  if (redraw) {
    drawAll();
    redraw = false;
  }
}

// =======================================================
// Энкодер
// =======================================================
void pollEnc() {
  int cur = digitalRead(PIN_CLK);
  if (cur != lastClk && cur == LOW) {
    bool cw = (digitalRead(PIN_DT) == HIGH);
    int dir = cw ? 1 : -1;
    switch (st) {
      case NORMAL: break;
      case MENU:
        menuIdx = constrain(menuIdx + dir, 0, N_MENU - 1);
        break;
      case SET_TEMP:
        editVal = constrain(editVal + dir * 0.5, 0.0, 100.0);
        break;
      case SET_KP:
        editVal = constrain(editVal + dir * 0.5, 0.0, 50.0);
        break;
      case SET_KI:
        editVal = constrain(editVal + dir * 0.05, 0.0, 5.0);
        break;
      case SET_KD:
        editVal = constrain(editVal + dir * 0.5, 0.0, 20.0);
        break;
      case SET_DELTA:
        editVal = constrain(editVal + dir * 0.25, 0.0, 20.0);
        break;
      case SET_TIMER:
        editVal = constrain(editVal + dir * 1.0, 0.0, 600.0);
        break;
      case CAL_MIN:
        sPos = constrain(sPos + dir, 0, sMax - 1);
        srv.write(sPos);
        break;
      case CAL_MAX:
        sPos = constrain(sPos + dir, sMin + 1, 180);
        srv.write(sPos);
        break;
      case AUTOTUNE: break;
      case PRESET_LIST:
        presetSlot = constrain(presetSlot + dir, 0, N_PRESETS - 1);
        break;
      case PRESET_ACTION:
        presetActionIdx = constrain(presetActionIdx + dir, 0, 2);
        break;
      case PRESET_NAME:
        nameCharIdx[nameCursor] = constrain(nameCharIdx[nameCursor] + dir, 0, charsetLen - 1);
        nameBuf[nameCursor] = charset[nameCharIdx[nameCursor]];
        break;
    }
    redraw = true;
  }
  lastClk = cur;
}

// =======================================================
// Кнопки
// =======================================================
void pollBtns() {
  unsigned long now = millis();
  if (digitalRead(PIN_BACK) == LOW && now - dbBack > DB_MS) {
    if (!bBack) { bBack = true; onBack(); }
    dbBack = now;
  } else if (digitalRead(PIN_BACK) == HIGH) bBack = false;

  if (digitalRead(PIN_OK) == LOW && now - dbOk > DB_MS) {
    if (!bOk) { bOk = true; onOk(); }
    dbOk = now;
  } else if (digitalRead(PIN_OK) == HIGH) bOk = false;

  if (digitalRead(PIN_SW) == LOW && now - dbSw > DB_MS) {
    if (!bSw) { bSw = true; onSw(); }
    dbSw = now;
  } else if (digitalRead(PIN_SW) == HIGH) bSw = false;
}

void onOk() {
  switch (st) {
    case NORMAL:
      st = MENU;
      menuIdx = 0;
      atAutoStartPending = false;
      break;
    case MENU:
      switch (menuIdx) {
        case 0: st = SET_TEMP;  editVal = setpoint;          break;
        case 1: st = SET_KP;    editVal = Kp;                break;
        case 2: startAutoTune(false);                         break;
        case 3: st = SET_DELTA; editVal = timerDelta;        break;
        case 4: st = CAL_MIN;   sPos = sMin; srv.write(sPos); break;
        case 5: presetIsTemp = true;  presetSlot = 0; st = PRESET_LIST; break;
        case 6: presetIsTemp = false; presetSlot = 0; st = PRESET_LIST; break;
        case 7: enterNormal();                                  break;
      }
      break;
    case PRESET_LIST:
      onSw();
      return;
    case PRESET_ACTION:
      onSw();
      return;
    case PRESET_NAME:
      savePresetWithName();
      st = PRESET_ACTION;
      lastActionWasErase = false;
      break;
    default: break;
  }
  redraw = true;
}

void onBack() {
  switch (st) {
    case MENU:      enterNormal();                        break;
    case SET_TEMP:
    case SET_KP:
    case SET_DELTA: st = MENU;                            break;
    case SET_KI:    st = SET_KP;  editVal = Kp;            break;
    case SET_KD:    st = SET_KI;  editVal = Ki;            break;
    case SET_TIMER: st = SET_DELTA; editVal = timerDelta; break;
    case AUTOTUNE:
      atPhase = AT_OFF;
      st = (atAutomatic) ? NORMAL : MENU;
      sPos = sMin; srv.write(sPos);
      atSessionDone = true;
      if (atAutomatic) resetPID();
      break;
    case CAL_MIN:
      st = MENU;
      sPos = constrain(sPos, sMin, sMax);
      srv.write(sPos);
      break;
    case CAL_MAX:
      st = CAL_MIN;
      sPos = sMin; srv.write(sPos);
      break;
    case PRESET_LIST:
      st = MENU;
      break;
    case PRESET_ACTION:
      st = PRESET_LIST;
      break;
    case PRESET_NAME:
      if (nameCursor > 0) {
        nameCursor--;
      } else {
        st = PRESET_ACTION;
      }
      break;
    default: break;
  }
  redraw = true;
}

void onSw() {
  switch (st) {
    case NORMAL:
      if (tmSt == TM_DONE) {
        tmSt = (timerDuration > 0) ? TM_IDLE : TM_OFF;
        resetPID();
      } else {
        resetPID();
      }
      break;
    case MENU:
      onOk();
      return;
    case SET_TEMP:
      setpoint = editVal; saveAllEEPROM(); savedT = millis();
      tmSt = (timerDuration > 0) ? TM_IDLE : TM_OFF;
      enterNormal();
      break;
    case SET_KP:
      Kp = editVal; saveAllEEPROM(); savedT = millis();
      st = SET_KI; editVal = Ki;
      break;
    case SET_KI:
      Ki = editVal; saveAllEEPROM(); savedT = millis();
      st = SET_KD; editVal = Kd;
      break;
    case SET_KD:
      Kd = editVal; saveAllEEPROM(); savedT = millis();
      enterNormal();
      break;
    case SET_DELTA:
      timerDelta = editVal; saveAllEEPROM(); savedT = millis();
      st = SET_TIMER; editVal = (float)timerDuration;
      break;
    case SET_TIMER:
      timerDuration = (int)editVal; saveAllEEPROM(); savedT = millis();
      tmSt = (timerDuration > 0) ? TM_IDLE : TM_OFF;
      enterNormal();
      break;
    case AUTOTUNE:
      if (atPhase == AT_RESULT) applyAutoTuneResults();
      break;
    case CAL_MIN:
      sMin = sPos; saveAllEEPROM(); savedT = millis();
      st = CAL_MAX; sPos = sMax; srv.write(sPos);
      break;
    case CAL_MAX:
      sMax = sPos; saveAllEEPROM(); savedT = millis();
      enterNormal();
      break;

    case PRESET_LIST:
      st = PRESET_ACTION;
      presetActionIdx = 0;
      break;

    case PRESET_ACTION: {
      bool valid;
      char name[NAME_LEN + 1];
      if (presetActionIdx == 0) {
        if (presetIsTemp) {
          float sp; int dur;
          readTempPreset(presetSlot, sp, dur, name, valid);
          if (valid) {
            setpoint = sp;
            timerDuration = dur;
            saveAllEEPROM();
            tmSt = (timerDuration > 0) ? TM_IDLE : TM_OFF;
            savedT = millis();
            lastActionWasErase = false;
            enterNormal();
          }
        } else {
          float kp, ki, kd;
          readPIDPreset(presetSlot, kp, ki, kd, name, valid);
          if (valid) {
            Kp = kp; Ki = ki; Kd = kd;
            saveAllEEPROM();
            resetPID();
            savedT = millis();
            lastActionWasErase = false;
            enterNormal();
          }
        }
      } else if (presetActionIdx == 1) {
        initNameEditor();
        st = PRESET_NAME;
      } else {
        if (presetIsTemp)
          eraseTempPreset(presetSlot);
        else
          erasePIDPreset(presetSlot);
        savedT = millis();
        lastActionWasErase = true;
      }
      break;
    }

    case PRESET_NAME:
      nameCursor = (nameCursor + 1) % NAME_LEN;
      break;
  }
  redraw = true;
}

