// Температура
// =======================================================
void pollTemp() {
  unsigned long now = millis();
  if (!tReq && now - tLast > T_INTERVAL) {
    ts.requestTemperatures();
    tReq = true;
    tReqT = now;
  }
  if (tReq && now - tReqT > T_CONV) {
    float t = ts.getTempCByIndex(0);
    bool err = (t == -127.0);
    if (tErr && !err) resetPID();
    temp = t;
    tErr = err;
    tReq = false;
    tLast = now;
    tempReady = true;
    redraw = true;
  }
}

