    case SET_KP:        drawPID(0);        break;
    case SET_KI:        drawPID(1);        break;
    case SET_KD:        drawPID(2);        break;
    case AUTOTUNE:      drawAutoTune();    break;
    case SET_DELTA:     drawTimer(0);      break;
    case SET_TIMER:     drawTimer(1);      break;
    case CAL_MIN:       drawCal(true);     break;
    case CAL_MAX:       drawCal(false);    break;
    case PRESET_LIST:   drawPresetList();  break;
    case PRESET_ACTION: drawPresetAction();break;
    case PRESET_NAME:   drawPresetName();  break;
