  dsp.display();
}

void header(const char* t) {
  dsp.setCursor(0, 0);
  dsp.println(t);
  dsp.drawLine(0, 10, 127, 10, SSD1306_WHITE);
  dsp.setCursor(0, 14);
}

bool showSaved() {
  return (savedT > 0 && millis() - savedT < 800);
}

void formatTime(unsigned long sec, char* buf) {
  int m = sec / 60;
  int s = sec % 60;
  sprintf(buf, "%d:%02d", m, s);
}

void drawNormal() {
  header("Temp Controller");
  dsp.print("Set:  ");
  dsp.print(setpoint, 1);
  dsp.write(247);
  dsp.print("C  D:");
  dsp.print(timerDelta, 2);
  dsp.println("");
  dsp.print("Temp: ");
  if (tErr) { dsp.println("---"); }
  else {
    dsp.print(temp, 1);
    dsp.write(247);
    dsp.print("C  ");
    char tbuf[8];
    switch (tmSt) {
      case TM_OFF:  dsp.println("");        break;
      case TM_IDLE: dsp.println("T:Ready"); break;
      case TM_RUN:  formatTime(tmRemain, tbuf); dsp.print("T:"); dsp.println(tbuf); break;
      case TM_DONE: dsp.println("T:DONE");  break;
    }
  }
  if (!tErr) {
    dsp.print("Err:  ");
    float err = setpoint - temp;
    if (err >= 0) dsp.print("+");
    dsp.print(err, 1);
    dsp.write(247);
    dsp.println("C");
  } else dsp.println("Err:  ---");
  dsp.print("Out:  ");
  dsp.print(sPos);
  dsp.print(" ["); dsp.print(sMin);
  dsp.print("~"); dsp.print(sMax); dsp.println("]");
  dsp.println("");
  if (showSaved())         dsp.println(">> SAVED!");
  else if (tmSt == TM_DONE) dsp.println("SW:Reset Timer");
  else                      dsp.println("OK:Menu SW:Reset");
}

