// ----- Список пресетов -----
void drawPresetList() {
  header(presetIsTemp ? "Temp Presets" : "PID Presets");
  int maxLines = 5;
  int startIdx = presetSlot - 2;
  if (startIdx < 0) startIdx = 0;
  if (startIdx + maxLines > N_PRESETS) startIdx = N_PRESETS - maxLines;
  int endIdx = min(N_PRESETS, startIdx + maxLines);

  for (int i = startIdx; i < endIdx; i++) {
    bool valid;
    char name[NAME_LEN + 1];
    if (presetIsTemp) {
      float sp; int dur;
      readTempPreset(i, sp, dur, name, valid);
    } else {
      float kp, ki, kd;
      readPIDPreset(i, kp, ki, kd, name, valid);
    }
    if (i == presetSlot) {
      dsp.setTextColor(SSD1306_BLACK, SSD1306_WHITE);
      dsp.print(">");
    } else {
      dsp.setTextColor(SSD1306_WHITE);
      dsp.print(" ");
    }
    dsp.print(i);
    dsp.print(":");
    if (valid) {
      int last = 13;
      while (last >= 0 && name[last] == ' ') last--;
      for (int j = 0; j <= last; j++)
        dsp.print(name[j]);
      dsp.println("");
    } else {
      dsp.println("[empty]");
    }
    dsp.setTextColor(SSD1306_WHITE);
  }
  dsp.println("");
  dsp.println("ENC:Scroll SW:Select");
  dsp.println("BK:Back");
}

